-- 只可在已核对名称的 IAM local/test Schema 执行；按固定 UUID 精确清理 T12D.1 Seed，不得用于生产。
-- 四个用户：student1、teacher1、teacher2、admin1；协议正文是固定 local-v1 测试版本。
DELETE FROM teacher_application_command WHERE application_id IN (
    SELECT id FROM teacher_application WHERE user_id IN (
        '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000102',
        '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000103')
);
DELETE FROM teacher_application WHERE user_id IN (
    '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000102',
    '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000103');
DELETE FROM identity_change_command WHERE user_id IN (
    '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000102',
    '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000103');
DELETE FROM admin_account_command WHERE actor_id IN (
    '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000102',
    '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000103')
  OR target_user_id IN (
    '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000102',
    '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000103');
DELETE FROM account_security_audit WHERE user_id IN (
    '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000102',
    '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000103')
  OR actor_id IN (
    '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000102',
    '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000103');
DELETE FROM login_audit WHERE user_id IN (
    '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000102',
    '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000103');
DELETE FROM protocol_agreement WHERE user_id IN (
    '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000102',
    '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000103');
DELETE FROM registration_request WHERE user_id IN (
    '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000102',
    '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000103');
DELETE FROM user_identity WHERE user_id IN (
    '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000102',
    '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000103');
DELETE FROM refresh_session WHERE user_id IN (
    '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000102',
    '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000103');
DELETE FROM user_role WHERE user_id IN (
    '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000102',
    '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000103');
DELETE FROM `user` WHERE id IN (
    '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000102',
    '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000103');
DELETE FROM protocol_document WHERE id IN (
    '00000000-0000-4000-8000-000000001301', '00000000-0000-4000-8000-000000001302');

-- 仅当这些角色/权限不再被任何其他测试数据引用时清理，避免扩大删除范围。
DELETE FROM role_permission WHERE role_id IN (
    SELECT role_id FROM (
        SELECT r.id AS role_id FROM `role` r LEFT JOIN user_role ur ON ur.role_id = r.id
        WHERE r.code IN ('STUDENT', 'TEACHER', 'ADMIN') AND ur.user_id IS NULL
    ) removable_roles
);
DELETE FROM permission WHERE code IN ('learning:access', 'teaching:access', 'administration:access')
  AND NOT EXISTS (SELECT 1 FROM role_permission rp WHERE rp.permission_id = permission.id);
DELETE FROM `role` WHERE code IN ('STUDENT', 'TEACHER', 'ADMIN')
  AND NOT EXISTS (SELECT 1 FROM user_role ur WHERE ur.role_id = `role`.id);
